**Shared helper (implement once for the whole effort):**

```csharp
// ORBIT.Model/Helper/ReferenceCache.cs  — implement ONCE for the whole effort.
using Microsoft.Extensions.Caching.Memory;

namespace ORBIT.Model.Helper
{
    public static class ReferenceCache
    {
        private static readonly IMemoryCache _cache =
            new MemoryCache( new MemoryCacheOptions( ) );
        private static readonly TimeSpan DefaultTtl = TimeSpan.FromHours( 4 );

        public static T GetOrAdd<T>( String key, Func<T> factory )
        {
            return _cache.GetOrCreate( key, entry =>
            {
                entry.AbsoluteExpirationRelativeToNow = DefaultTtl;
                return factory( );
            } );
        }

        public static void Invalidate( String key ) => _cache.Remove( key );
    }
}
```

