```csharp
// ORBIT.Model/Helper/RedisCache.cs  — implement ONCE. Call RedisCache.Initialize(mux)
// at startup with the app's existing StackExchange.Redis multiplexer.
using System.Text.Json;
using StackExchange.Redis;

namespace ORBIT.Model.Helper
{
    public static class RedisCache
    {
        private static IConnectionMultiplexer _mux;
        public static void Initialize( IConnectionMultiplexer mux ) => _mux = mux;
        private static readonly TimeSpan DefaultTtl = TimeSpan.FromHours( 4 );

        public static T GetOrAdd<T>( String key, Func<T> factory, TimeSpan? ttl = null )
        {
            IDatabase db = _mux?.GetDatabase( );
            if ( db == null ) return factory( );          // not configured -> source
            try
            {
                RedisValue cached = db.StringGet( key );
                if ( cached.HasValue ) return JsonSerializer.Deserialize<T>( cached! );
            }
            catch { return factory( ); }                  // Redis hiccup -> source
            T value = factory( );
            try { db.StringSet( key, JsonSerializer.Serialize( value ), ttl ?? DefaultTtl ); }
            catch { /* best-effort cache write */ }
            return value;
        }

        public static void Invalidate( String key )
        {
            try { _mux?.GetDatabase( ).KeyDelete( key ); }
            catch { /* best-effort */ }
        }
    }
}
```

